import type { Run } from "./schema.ts";

/**
 * Which revision of the CRAFTS workflow produced a run.
 *
 * The workflow changes — phases merge, agents collapse, gates appear. Metrics
 * collected across a change describe two different workflows averaged together,
 * which is worse than no metrics: it looks like signal. This happened already.
 * Every recorded `counsel` phase used the three-agent plan-review panel, so its
 * ~12 min/invoke is a panel's wall time; the single-reviewer `craft-counsel` that
 * replaced it has never been measured, and averaging the two would have silently
 * mixed them.
 *
 * Going forward the conductor declares the version at `start`. Backward, runs
 * predate the flag entirely, so their shape is inferred from what they actually
 * spawned. Inference is marked as such — a guess must never be mistaken for a
 * declaration.
 */

export type VersionSource = "declared" | "inferred" | "unknown";

/** Current toolkit version. Bump when a phase's shape changes: agents added or
 *  removed, duties moved between phases, gates introduced. Not for wording. */
export const CURRENT_CRAFT_VERSION = "4";

/**
 * Shape fingerprints, most recent first. Each entry lists agent-name fragments and
 * structural markers that only exist in that revision. Any single hit is decisive —
 * these are agents that were removed outright, not renamed, so their presence dates
 * a run unambiguously.
 */
const SIGNATURES: Array<{ version: string; agents: string[]; structural: (run: Run) => boolean }> = [
	{
		version: "4",
		// Single merged counsel reviewer; simplify and Sharpen folded into the
		// conductor; verify gate, payload blinding, and the R decision record added.
		agents: ["craft-counsel"],
		structural: (run) =>
			run.verify_count > 0 ||
			run.phases.some((p) => p.decisions !== undefined || p.plan_deviations !== undefined || p.blinding_scrubs > 0),
	},
	{
		version: "3",
		// Three-agent plan-review panel, with simplify and Sharpen as spawned agents.
		agents: ["craft-plan-", "craft-code-simplifier", "craft-sharpener"],
		structural: () => false,
	},
];

function agentText(run: Run): string {
	// Agent fields have historically held a comma-joined list for parallel spawns
	// (one `phase_enter` naming all three counsel reviewers), so match on substrings
	// rather than comparing whole values.
	const parts: string[] = [];
	for (const p of run.phases) {
		if (p.agent) parts.push(p.agent);
		parts.push(...p.agents);
	}
	return parts.join(",");
}

/**
 * Infer which workflow revision a run came from. Returns undefined when the run
 * carries no distinguishing marks — a bare run with no agents recorded could be
 * any version, and saying so is more useful than picking one.
 */
export function inferCraftVersion(run: Run): string | undefined {
	const text = agentText(run);
	const matched = SIGNATURES.filter((s) => s.agents.some((a) => text.includes(a)) || s.structural(run));
	// Signals from two revisions in one run means the fingerprints are wrong or the
	// toolkit changed mid-run. Either way, refuse rather than pick.
	if (matched.length !== 1) return undefined;
	return matched[0].version;
}

/**
 * Resolve a run's version and how confidently. Declared always wins; inference
 * only fills gaps left by runs recorded before the flag existed.
 */
export function resolveCraftVersion(run: Run): { version: string | undefined; source: VersionSource } {
	if (run.craft_version) return { version: run.craft_version, source: "declared" };
	const inferred = inferCraftVersion(run);
	if (inferred) return { version: inferred, source: "inferred" };
	return { version: undefined, source: "unknown" };
}

/**
 * Annotate a folded run in place, so callers can group without re-deriving.
 *
 * A version already recorded in the log wins — whether the skill declared it or
 * an earlier inference was persisted. Re-inferring over a persisted value would
 * make the stored record pointless and could silently disagree with it after a
 * classifier change, which is the opposite of why it was stored.
 */
export function applyCraftVersion(run: Run): void {
	if (run.craft_version_source) return;
	const { version, source } = resolveCraftVersion(run);
	run.craft_version = version;
	run.craft_version_source = source;
}

src/agent-port.ts.source:
/**
 * Translate a CRAFTS agent definition into Claude Code's dialect.
 *
 * The agent files in `agents/` are written for Pi: lowercase tool names, an
 * `input_schema`, and presentation keys Claude Code has no use for. Claude Code
 * wants `name`, `description`, and a comma-separated `tools` line.
 *
 * These are *generated*, never hand-maintained. Two copies of an agent prompt drift,
 * and the drift is invisible until a reviewer behaves differently on one host than
 * the other — which is exactly the comparison the metrics exist to make.
 */

/**
 * Pi's tool vocabulary → Claude Code's, and Claude Code's onto itself.
 *
 * The identity half makes porting idempotent, so re-running the generator over its
 * own output is a no-op rather than an agent that silently comes back with no tools.
 */
export const TOOL_MAP: Record<string, string> = {
	read: "Read",
	write: "Write",
	edit: "Edit",
	grep: "Grep",
	// Pi's `find` is a path search, which is Glob here — not the Bash `find` binary.
	find: "Glob",
	bash: "Bash",
	// Claude Code has called this both things; `Agent` is the current name.
	subagent: "Agent",
	Read: "Read",
	Write: "Write",
	Edit: "Edit",
	Grep: "Grep",
	Glob: "Glob",
	Bash: "Bash",
	Agent: "Agent",
};

/**
 * Frontmatter keys that exist only for Pi. Listed rather than inferred so that a new
 * key added upstream reaches `portAgent` as an unknown and gets a decision, instead
 * of being silently carried into a file Claude Code will not understand.
 */
const PI_ONLY = new Set([
	"context",
	"extensions",
	"input_schema",
	"color",
	"icon",
	"priority",
	"command",
	"acceptanceRole",
	"completionGuard",
]);

export interface PortedAgent {
	name: string;
	description: string;
	tools: string[];
	body: string;
}

export class PortError extends Error {}

interface Frontmatter {
	scalars: Map<string, string>;
	tools: string[];
	keys: string[];
}

/**
 * Read the leading `---` block. Deliberately not a YAML parser: the inputs are a
 * fixed set of `key: value` lines plus one list, and a real parser would be a
 * dependency this repo does not otherwise carry.
 */
function parseFrontmatter(source: string): { front: Frontmatter; body: string } {
	const lines = source.split("\n");
	if (lines[0]?.trim() !== "---") throw new PortError("no frontmatter block");
	const end = lines.indexOf("---", 1);
	if (end === -1) throw new PortError("unterminated frontmatter block");

	const scalars = new Map<string, string>();
	const keys: string[] = [];
	const tools: string[] = [];
	let inTools = false;
	for (const line of lines.slice(1, end)) {
		const item = /^\s+-\s+(.*)$/.exec(line);
		if (item) {
			if (inTools) tools.push(unquote(item[1]));
			continue;
		}
		const entry = /^([A-Za-z_][\w-]*):\s*(.*)$/.exec(line);
		if (!entry) continue;
		const [, key, rest] = entry;
		keys.push(key);
		inTools = key === "tools";
		if (inTools) {
			// Two spellings: Pi's block list (handled above) and the inline comma form
			// this generator itself emits. Reading only the first would drop every tool
			// when porting an already-ported file.
			for (const tool of rest.split(",")) {
				const name = unquote(tool);
				if (name) tools.push(name);
			}
			continue;
		}
		if (rest !== "") scalars.set(key, unquote(rest));
	}
	return { front: { scalars, tools, keys }, body: lines.slice(end + 1).join("\n") };
}

function unquote(value: string): string {
	const trimmed = value.trim();
	const quoted = /^"(.*)"$|^'(.*)'$/.exec(trimmed);
	return quoted ? (quoted[1] ?? quoted[2]) : trimmed;
}

/**
 * Port one agent file. Throws rather than guessing: an agent that silently loses a
 * tool still loads, still runs, and quietly cannot do its job.
 */
export function portAgent(source: string): PortedAgent {
	const { front, body } = parseFrontmatter(source);
	const name = front.scalars.get("name");
	const description = front.scalars.get("description");
	if (!name) throw new PortError("frontmatter has no name");
	if (!description) throw new PortError(`${name}: frontmatter has no description`);

	const tools = front.tools.map((tool) => {
		const mapped = TOOL_MAP[tool];
		if (!mapped) throw new PortError(`${name}: no Claude Code equivalent for tool \`${tool}\``);
		return mapped;
	});

	for (const key of front.keys) {
		if (key === "name" || key === "description" || key === "tools") continue;
		if (PI_ONLY.has(key)) continue;
		// `model` is the one that matters: the repo sets none on purpose, so each host
		// routes the agent itself. A ported file that pins one would shadow that.
		throw new PortError(`${name}: unhandled frontmatter key \`${key}\` — decide whether Claude Code needs it`);
	}

	return { name, description, tools, body };
}

/** Render the ported agent as a Claude Code agent file. */
export function renderAgent(agent: PortedAgent): string {
	const front = [
		"---",
		`name: ${agent.name}`,
		`description: ${agent.description}`,
		// Omitting `tools` entirely would grant every tool, so an empty list is written
		// as an empty list.
		`tools: ${agent.tools.join(", ")}`,
		"---",
	];
	// No `model`: see portAgent. Body carried through byte-for-byte — it is the
	// agent's actual instructions, and this translation is about frontmatter only.
	return `${front.join("\n")}\n${agent.body}`;
}

src/diff-ranges.ts.source:
/**
 * Changed-line ranges from a git diff, in the form mutation testing needs.
 *
 * Scoping mutation to the lines Render actually touched is what makes it cheap
 * enough to run every time — a 20-line range costs ~2s against ~44s for a whole
 * source tree — and, more importantly, what makes the result readable. Mutating
 * whole files surfaces pre-existing survivors that Render did not cause, and
 * those drown the ones it did.
 *
 * The parsing is small but the edge cases are not, so it lives apart from the
 * runner and is tested directly: an off-by-one here silently mutates the wrong
 * code and reports confidently about it.
 */

export interface LineRange {
	file: string;
	start: number;
	end: number;
}

/** `@@ -oldStart,oldCount +newStart,newCount @@` — counts are omitted when 1. */
const HUNK = /^@@ -\d+(?:,\d+)? \+(\d+)(?:,(\d+))? @@/;
// `b/` is optional so that `+++ /dev/null` matches too. It must: a deleted file
// needs to clear the current file, and if the header does not match at all the
// previous file stays current and the deletion's hunks are attributed to it.
// Deletions happen to carry `+0,0` hunks that are dropped anyway, so this was
// previously correct only by luck.
const FILE_HEADER = /^\+\+\+ (?:b\/)?(.+)$/;

/**
 * Parse `git diff --unified=0` output into per-file added/modified line ranges.
 *
 * Only `+` side lines matter: a mutation range must point at code that exists in
 * the working tree. A pure deletion (`+0,0`) yields no range — there is nothing
 * left to mutate — which is correct, not an omission.
 */
export function parseDiffRanges(diff: string): LineRange[] {
	const ranges: LineRange[] = [];
	let file: string | null = null;
	for (const line of diff.split("\n")) {
		const header = FILE_HEADER.exec(line);
		if (header) {
			// `/dev/null` on the + side means the file was deleted; nothing to mutate.
			file = header[1] === "/dev/null" ? null : header[1];
			continue;
		}
		if (!file) continue;
		const hunk = HUNK.exec(line);
		if (!hunk) continue;
		const start = Number(hunk[1]);
		// An absent count means exactly one line. A count of zero means the change
		// was a deletion anchored after `start`, so there is no new line to mutate.
		const count = hunk[2] === undefined ? 1 : Number(hunk[2]);
		if (count === 0) continue;
		ranges.push({ file, start, end: start + count - 1 });
	}
	return ranges;
}

/**
 * Keep only ranges in files worth mutating: source, not tests, and matching the
 * caller's source globs. Mutating a test file is meaningless — the mutant would
 * be "killed" by definition or break the run.
 */
export function filterSourceRanges(
	ranges: LineRange[],
	opts: { include: RegExp[]; exclude: RegExp[] },
): LineRange[] {
	return ranges.filter(
		(r) => opts.include.some((re) => re.test(r.file)) && !opts.exclude.some((re) => re.test(r.file)),
	);
}

/**
 * Merge ranges that touch or overlap within a file. Adjacent diff hunks often
 * abut after filtering, and collapsing them keeps the `--mutate` argument short
 * enough to stay under argv limits on a large diff.
 */
export function mergeRanges(ranges: LineRange[]): LineRange[] {
	const byFile = new Map<string, LineRange[]>();
	for (const r of ranges) {
		const list = byFile.get(r.file) ?? [];
		list.push(r);
		byFile.set(r.file, list);
	}
	const out: LineRange[] = [];
	for (const [file, list] of [...byFile.entries()].sort((a, b) => a[0].localeCompare(b[0]))) {
		list.sort((a, b) => a.start - b.start);
		let cur = { ...list[0] };
		for (const r of list.slice(1)) {
			// `<= cur.end + 1` merges abutting ranges, not just overlapping ones.
			if (r.start <= cur.end + 1) {
				cur.end = Math.max(cur.end, r.end);
			} else {
				out.push(cur);
				cur = { ...r };
			}
		}
		out.push(cur);
		void file;
	}
	return out;
}

/**
 * Stryker's mutation-range syntax: `file:startLine:startCol-endLine:endCol`.
 * Column 1 to column 1 of the following line covers a whole line inclusively.
 */
export function toStrykerMutateArgs(ranges: LineRange[]): string[] {
	return ranges.map((r) => `${r.file}:${r.start}:1-${r.end + 1}:1`);
}

/** Total lines covered, for the size cap that decides whether to run at all. */
export function countLines(ranges: LineRange[]): number {
	return ranges.reduce((sum, r) => sum + (r.end - r.start + 1), 0);
}

