import { mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { test } from "node:test";
import assert from "node:assert/strict";
import {
	applyNotionalPricing,
	bundledPriceTablePath,
	loadPriceTable,
	mergePriceTables,
	notionalCostForTokens,
	type PriceTable,
} from "../src/pricing.ts";
import { emptyPhase, emptyTokens, type Run } from "../src/schema.ts";

function tmpFile(content: string): { path: string; cleanup: () => void } {
	const dir = mkdtempSync(join(tmpdir(), "craft-pricing-"));
	const path = join(dir, "models-store.json");
	writeFileSync(path, content);
	return { path, cleanup: () => rmSync(dir, { recursive: true, force: true }) };
}

test("loadPriceTable parses provider/id from the models-store.json shape", () => {
	const { path, cleanup } = tmpFile(
		JSON.stringify({
			"openai-codex": {
				models: [
					{ id: "gpt-5.6-terra", cost: { input: 2, output: 12, cacheRead: 0.2, cacheWrite: 2.5 } },
					{ id: "gpt-5.6-sol", cost: { input: 5, output: 30, cacheRead: 0.5, cacheWrite: 6.25 } },
				],
			},
			xai: { models: [{ id: "grok-4.6", cost: { input: 2, output: 6, cacheRead: 0.5, cacheWrite: 0 } }] },
		}),
	);
	try {
		const table = loadPriceTable(path);
		assert.equal(table.size, 3);
		assert.deepEqual(table.get("openai-codex/gpt-5.6-terra"), {
			input: 2,
			output: 12,
			cacheRead: 0.2,
			cacheWrite: 2.5,
		});
		assert.deepEqual(table.get("xai/grok-4.6"), { input: 2, output: 6, cacheRead: 0.5, cacheWrite: 0 });
		assert.equal(table.get("xai/nonexistent"), undefined);
	} finally {
		cleanup();
	}
});

test("the bundled table prices the models Claude Code actually reports", () => {
	// Read through the explicit-path route so this asserts the shipped file itself,
	// not whatever this machine's pi registry happens to add on top.
	const bundled = loadPriceTable(bundledPriceTablePath());
	assert.deepEqual(bundled.get("anthropic/claude-opus-5"), {
		input: 5,
		output: 25,
		cacheRead: 0.5,
		cacheWrite: 6.25,
	});
	// Claude Code writes the dated Haiku id, not the alias — both must price.
	assert.ok(bundled.get("anthropic/claude-haiku-4-5-20251001"));
	// The prose block in the file is not a provider, and must not parse as one.
	assert.equal(bundled.get("_comment/models"), undefined);
});

test("the host's registry wins over the bundled price for the same model", () => {
	const bundled: PriceTable = new Map([
		["anthropic/claude-opus-5", { input: 5, output: 25, cacheRead: 0.5, cacheWrite: 6.25 }],
		["anthropic/claude-haiku-4-5", { input: 1, output: 5, cacheRead: 0.1, cacheWrite: 1.25 }],
	]);
	const registry: PriceTable = new Map([
		["anthropic/claude-opus-5", { input: 4, output: 20, cacheRead: 0.4, cacheWrite: 5 }],
		["xai/grok-4.6", { input: 2, output: 6, cacheRead: 0.5, cacheWrite: 0 }],
	]);

	const merged = mergePriceTables(bundled, registry);
	assert.equal(merged.get("anthropic/claude-opus-5")!.input, 4, "the host knows its own routing better");
	assert.equal(merged.get("anthropic/claude-haiku-4-5")!.input, 1, "and does not erase what it never listed");
	assert.equal(merged.get("xai/grok-4.6")!.input, 2);
	assert.equal(bundled.size, 2, "inputs are left alone");
	assert.equal(registry.size, 2);
});

test("an explicit price table is used exactly, with no bundled prices merged under it", () => {
	const { path, cleanup } = tmpFile(JSON.stringify({ xai: { models: [{ id: "grok-4.6", cost: { input: 2 } }] } }));
	const prior = process.env.CRAFT_METRICS_PRICES;
	try {
		assert.equal(loadPriceTable(path).get("anthropic/claude-opus-5"), undefined, "argument form");
		process.env.CRAFT_METRICS_PRICES = path;
		assert.equal(loadPriceTable().get("anthropic/claude-opus-5"), undefined, "env form");
	} finally {
		if (prior === undefined) delete process.env.CRAFT_METRICS_PRICES;
		else process.env.CRAFT_METRICS_PRICES = prior;
		cleanup();
	}
});

test("the default resolution prices Anthropic models even when the host registry lists none", () => {
	const prior = process.env.CRAFT_METRICS_PRICES;
	delete process.env.CRAFT_METRICS_PRICES;
	try {
		assert.ok(
			loadPriceTable().get("anthropic/claude-opus-5"),
			"a Claude Code phase must price against something — it reports no cost of its own",
		);
	} finally {
		if (prior !== undefined) process.env.CRAFT_METRICS_PRICES = prior;
	}
});

test("loadPriceTable never throws — missing file, bad json, and wrong shape all yield empty", () => {
	assert.equal(loadPriceTable("/definitely/does/not/exist.json").size, 0);
	const { path: badJson, cleanup: c1 } = tmpFile("{ not valid json");
	try {
		assert.equal(loadPriceTable(badJson).size, 0);
	} finally {
		c1();
	}
	const { path: wrongShape, cleanup: c2 } = tmpFile(JSON.stringify({ openai: "not an object with models" }));
	try {
		assert.equal(loadPriceTable(wrongShape).size, 0);
	} finally {
		c2();
	}
	const { path: skipsBadEntries, cleanup: c3 } = tmpFile(
		JSON.stringify({
			p: { models: [{ id: "no-cost-field" }, { id: "good", cost: { input: 1, output: 2, cacheRead: 0, cacheWrite: 0 } }] },
		}),
	);
	try {
		const table = loadPriceTable(skipsBadEntries);
		assert.equal(table.size, 1);
		assert.ok(table.has("p/good"));
	} finally {
		c3();
	}
});

test("notionalCostForTokens prices per-million-token, matching provider convention", () => {
	const price = { input: 2, output: 12, cacheRead: 0.2, cacheWrite: 2.5 };
	const cost = notionalCostForTokens(price, { input: 1_000_000, output: 500_000, cacheRead: 8_000_000, cacheWrite: 0 });
	// (1M*2 + 0.5M*12 + 8M*0.2) / 1e6 = 2 + 6 + 1.6
	assert.ok(Math.abs(cost - 9.6) < 1e-9);
});

test("notionalCostForTokens on zero tokens is zero, not NaN", () => {
	const price = { input: 2, output: 12, cacheRead: 0.2, cacheWrite: 2.5 };
	assert.equal(notionalCostForTokens(price, emptyTokens()), 0);
});

function bareRun(): Run {
	return {
		schema_version: 1,
		run_id: "r1",
		started_at: "2026-01-01T00:00:00.000Z",
		ended_at: null,
		host: "pi",
		cwd: "/tmp",
		mode: "full",
		outcome: "open",
		open_phase: null,
		phase_entries: 0,
		last_closed_phase: null,
		last_closed_at: null,
		phases: [],
		seams: { counsel_family_differs_from_c: null, a_family_differs_from_r: null, t_family_differs_from_r: null },
		hitl: { pause_ms: 0 },
		last_verify: null,
		verify_count: 0,
	};
}

test("applyNotionalPricing sums per-model spend into phase and run totals", () => {
	const run = bareRun();
	const a = emptyPhase("A");
	a.by_model["xai/grok-4.6"] = {
		provider: "xai",
		turns: 1,
		events: 1,
		cost_usd: 0,
		tokens: { input: 1_000_000, output: 0, cacheRead: 0, cacheWrite: 0 },
	};
	const r = emptyPhase("R");
	r.by_model["unpriced/thing"] = {
		provider: "unpriced",
		turns: 1,
		events: 1,
		cost_usd: 0.5, // no price entry — notional must fall back to this, not zero it out
		tokens: { input: 100, output: 0, cacheRead: 0, cacheWrite: 0 },
	};
	run.phases = [a, r];

	const table = new Map([["xai/grok-4.6", { input: 2, output: 6, cacheRead: 0.5, cacheWrite: 0 }]]);
	applyNotionalPricing(run, table);

	assert.equal(a.notional_cost_usd, 2); // 1M input * $2/M
	assert.equal(a.by_model["xai/grok-4.6"].notional_cost_usd, 2);
	assert.equal(r.notional_cost_usd, 0.5); // fell back to actual — no price for this model
	assert.equal(run.notional_cost_usd, 2.5);
});

test("applyNotionalPricing on an empty table falls back to actual everywhere", () => {
	const run = bareRun();
	const c = emptyPhase("C");
	c.by_model["zai/glm-5.2"] = {
		provider: "zai",
		turns: 1,
		events: 1,
		cost_usd: 0.03,
		tokens: { input: 500, output: 200, cacheRead: 0, cacheWrite: 0 },
	};
	run.phases = [c];
	applyNotionalPricing(run, new Map());
	assert.equal(c.notional_cost_usd, 0.03);
	assert.equal(run.notional_cost_usd, 0.03);
});

test/mutate.test.ts.source:
import { mkdtempSync, mkdirSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { test } from "node:test";
import assert from "node:assert/strict";
import { computeRanges, parseStrykerReport, runMutate } from "../src/mutate.ts";

function tmpRepo(withConfig = true): { dir: string; cleanup: () => void } {
	const dir = mkdtempSync(join(tmpdir(), "craft-mutate-"));
	if (withConfig) writeFileSync(join(dir, "stryker.config.json"), "{}");
	return { dir, cleanup: () => rmSync(dir, { recursive: true, force: true }) };
}

function writeReport(dir: string, report: unknown): void {
	mkdirSync(join(dir, "reports", "mutation"), { recursive: true });
	writeFileSync(join(dir, "reports", "mutation", "mutation.json"), JSON.stringify(report));
}

const DIFF = ["--- a/src/a.ts", "+++ b/src/a.ts", "@@ -10,2 +10,3 @@", "+x"].join("\n");

test("skips silently when the repo has no stryker config", () => {
	const { dir, cleanup } = tmpRepo(false);
	try {
		const r = runMutate({ cwd: dir, base: "HEAD", gitDiff: () => DIFF, runStryker: () => ({ ok: true, timedOut: false }) });
		assert.equal(r.status, "skipped");
		assert.equal(r.reason, "no-backend");
	} finally {
		cleanup();
	}
});

test("skips when the diff touches no source lines", () => {
	const { dir, cleanup } = tmpRepo();
	try {
		const testOnly = ["--- a/test/a.test.ts", "+++ b/test/a.test.ts", "@@ -1,0 +2,3 @@", "+x"].join("\n");
		const r = runMutate({ cwd: dir, base: "HEAD", gitDiff: () => testOnly, runStryker: () => ({ ok: true, timedOut: false }) });
		assert.equal(r.status, "skipped");
		assert.equal(r.reason, "no-changes");
	} finally {
		cleanup();
	}
});

test("skips an oversize diff without running anything", () => {
	const { dir, cleanup } = tmpRepo();
	try {
		let ran = false;
		const big = ["--- a/src/a.ts", "+++ b/src/a.ts", "@@ -1,0 +1,5000 @@"].join("\n");
		const r = runMutate({
			cwd: dir,
			base: "HEAD",
			maxLines: 2000,
			gitDiff: () => big,
			runStryker: () => {
				ran = true;
				return { ok: true, timedOut: false };
			},
		});
		assert.equal(r.status, "skipped");
		assert.equal(r.reason, "oversize");
		assert.equal(r.lines_scoped, 5000);
		assert.equal(ran, false, "must not invoke the backend for an oversize diff");
	} finally {
		cleanup();
	}
});

test("reports a timeout as skipped rather than an error", () => {
	const { dir, cleanup } = tmpRepo();
	try {
		const r = runMutate({
			cwd: dir,
			base: "HEAD",
			gitDiff: () => DIFF,
			runStryker: () => ({ ok: false, timedOut: true }),
		});
		assert.equal(r.status, "skipped");
		assert.equal(r.reason, "timeout");
	} finally {
		cleanup();
	}
});

test("errors when the backend ran but produced no report", () => {
	const { dir, cleanup } = tmpRepo();
	try {
		const r = runMutate({
			cwd: dir,
			base: "HEAD",
			gitDiff: () => DIFF,
			runStryker: () => ({ ok: false, timedOut: false, detail: "boom" }),
		});
		assert.equal(r.status, "error");
		assert.equal(r.reason, "failed");
	} finally {
		cleanup();
	}
});

test("parses a real report shape into counts and survivors", () => {
	const { dir, cleanup } = tmpRepo();
	try {
		writeReport(dir, {
			files: {
				"src/a.ts": {
					mutants: [
						{ mutatorName: "ConditionalExpression", replacement: "false", status: "Killed", coveredBy: ["0"], location: { start: { line: 12 } } },
						{ mutatorName: "StringLiteral", replacement: '""', status: "Survived", coveredBy: ["0"], location: { start: { line: 59 } } },
						{ mutatorName: "BlockStatement", replacement: "{}", status: "NoCoverage", location: { start: { line: 80 } } },
						{ mutatorName: "ArithmeticOperator", replacement: "-", status: "Timeout", coveredBy: ["0"], location: { start: { line: 90 } } },
					],
				},
			},
			testFiles: { "test/a.test.ts": { tests: [{ id: "0", name: "does a thing" }] } },
		});
		const r = runMutate({ cwd: dir, base: "HEAD", gitDiff: () => DIFF, runStryker: () => ({ ok: true, timedOut: false }) });
		assert.equal(r.status, "ran");
		assert.equal(r.backend, "stryker");
		assert.equal(r.tested, 4);
		assert.equal(r.killed, 2, "a timeout counts as killed — behaviour changed detectably");
		assert.equal(r.survived, 1);
		assert.equal(r.no_coverage, 1);
		assert.deepEqual(r.survivors, [
			{ file: "src/a.ts", line: 59, mutator: "StringLiteral", replacement: '""', covered_by: ["test/a.test.ts"] },
		]);
	} finally {
		cleanup();
	}
});

test("statuses that say nothing about test quality are excluded from the count", () => {
	const parsed = parseStrykerReport({
		files: {
			"src/a.ts": {
				mutants: [
					{ mutatorName: "M", replacement: "x", status: "CompileError", location: { start: { line: 1 } } },
					{ mutatorName: "M", replacement: "x", status: "Ignored", location: { start: { line: 2 } } },
					{ mutatorName: "M", replacement: "x", status: "Killed", location: { start: { line: 3 } } },
				],
			},
		},
	});
	assert.equal(parsed.tested, 1);
	assert.equal(parsed.killed, 1);
});

test("a survivor nothing covered reports an empty test list, not a missing field", () => {
	const parsed = parseStrykerReport({
		files: { "src/a.ts": { mutants: [{ mutatorName: "M", replacement: "x", status: "Survived", location: { start: { line: 5 } } }] } },
	});
	assert.deepEqual(parsed.survivors[0].covered_by, []);
});

test("computeRanges merges and filters end to end", () => {
	const diff = [
		"--- a/src/a.ts",
		"+++ b/src/a.ts",
		"@@ -1,0 +10,2 @@",
		"+x",
		"@@ -1,0 +12,2 @@",
		"+y",
		"--- a/test/a.test.ts",
		"+++ b/test/a.test.ts",
		"@@ -1,0 +1,9 @@",
		"+z",
	].join("\n");
	assert.deepEqual(computeRanges(diff), [{ file: "src/a.ts", start: 10, end: 13 }]);
});

test("an untracked source file is scoped in full — git diff cannot see it", () => {
	const { dir, cleanup } = tmpRepo();
	try {
		writeReport(dir, { files: {}, testFiles: {} });
		let mutateArgs: string[] = [];
		const r = runMutate({
			cwd: dir,
			base: "HEAD",
			gitDiff: () => "", // a brand-new file produces no diff output at all
			untracked: () => [
				{ file: "src/brand-new.ts", lines: 40 },
				{ file: "test/brand-new.test.ts", lines: 20 }, // excluded: it is a test
				{ file: "README.md", lines: 10 }, // excluded: not source
			],
			runStryker: (_d, args) => {
				mutateArgs = args;
				return { ok: true, timedOut: false };
			},
		});
		assert.equal(r.status, "ran");
		assert.equal(r.lines_scoped, 40);
		assert.deepEqual(mutateArgs, ["src/brand-new.ts:1:1-41:1"]);
	} finally {
		cleanup();
	}
});

test("an empty untracked file scopes nothing rather than an invalid range", () => {
	assert.deepEqual(computeRanges("", [{ file: "src/empty.ts", lines: 0 }]), []);
});

test("tracked edits and new files combine into one scope", () => {
	const ranges = computeRanges(DIFF, [{ file: "src/new.ts", lines: 5 }]);
	assert.deepEqual(ranges, [
		{ file: "src/a.ts", start: 10, end: 12 },
		{ file: "src/new.ts", start: 1, end: 5 },
	]);
});

// --- gaps found by mutation testing, not by review ---

test("a diff exactly at the line cap runs; one line over is skipped", () => {
	// `>` vs `>=` at the boundary. Nothing previously tested the exact limit, so
	// the off-by-one was invisible.
	const at = ["--- a/src/a.ts", "+++ b/src/a.ts", "@@ -1,0 +1,100 @@"].join("\n");
	const over = ["--- a/src/a.ts", "+++ b/src/a.ts", "@@ -1,0 +1,101 @@"].join("\n");
	for (const [diff, expected] of [
		[at, "ran"],
		[over, "skipped"],
	] as const) {
		const { dir, cleanup } = tmpRepo();
		try {
			writeReport(dir, { files: {}, testFiles: {} });
			const r = runMutate({
				cwd: dir,
				base: "HEAD",
				maxLines: 100,
				gitDiff: () => diff,
				runStryker: () => ({ ok: true, timedOut: false }),
			});
			assert.equal(r.status, expected, `${r.lines_scoped} lines against a cap of 100`);
		} finally {
			cleanup();
		}
	}
});

test("the default excludes drop a test file that lives under src/", () => {
	// The end-to-end fixture used `test/a.test.ts`, which DEFAULT_INCLUDE rejects on
	// its own — so DEFAULT_EXCLUDE was never actually exercised. A test file inside
	// src/ passes the include and can only be dropped by the exclude.
	assert.deepEqual(computeRanges(["--- a/src/a.test.ts", "+++ b/src/a.test.ts", "@@ -1,0 +1,9 @@"].join("\n")), []);
	assert.deepEqual(computeRanges(["--- a/src/a.spec.ts", "+++ b/src/a.spec.ts", "@@ -1,0 +1,9 @@"].join("\n")), []);
});

test("duration is measured forward, not backward", () => {
	const { dir, cleanup } = tmpRepo();
	try {
		writeReport(dir, { files: {}, testFiles: {} });
		const r = runMutate({ cwd: dir, base: "HEAD", gitDiff: () => DIFF, runStryker: () => ({ ok: true, timedOut: false }) });
		// `>= 0` alone proves nothing: adding the two timestamps instead of
		// subtracting them also clears zero. An upper bound is what makes this an
		// assertion about an interval rather than about a number being positive.
		assert.ok(r.duration_ms !== undefined, "duration must be reported");
		assert.ok(r.duration_ms! >= 0 && r.duration_ms! < 60_000, `elapsed ms out of range: ${r.duration_ms}`);
	} finally {
		cleanup();
	}
});

test("a survivor covered by an unknown test id reports no test file rather than undefined", () => {
	const parsed = parseStrykerReport({
		files: { "src/a.ts": { mutants: [{ mutatorName: "M", replacement: "x", status: "Survived", coveredBy: ["99"], location: { start: { line: 5 } } }] } },
		testFiles: { "test/a.test.ts": { tests: [{ id: "0" }] } },
	});
	assert.deepEqual(parsed.survivors[0].covered_by, []);
});

// --- survivor cap: a reviewer gets a list it can actually rule on ---

function reportWith(n: number) {
	return {
		files: {
			"src/a.ts": {
				mutants: Array.from({ length: n }, (_, i) => ({
					mutatorName: "StringLiteral",
					replacement: `"m${i}"`,
					status: "Survived",
					coveredBy: ["0"],
					location: { start: { line: n - i } }, // reverse order, to prove sorting
				})),
			},
		},
		testFiles: { "test/a.test.ts": { tests: [{ id: "0" }] } },
	};
}

test("survivors are capped, and the remainder is counted rather than dropped silently", () => {
	const parsed = parseStrykerReport(reportWith(57), 20);
	assert.equal(parsed.survived, 57, "the true count is still reported");
	assert.equal(parsed.survivors.length, 20);
	assert.equal(parsed.survivors_omitted, 37);
});

test("a list under the cap reports nothing omitted", () => {
	const parsed = parseStrykerReport(reportWith(5), 20);
	assert.equal(parsed.survivors.length, 5);
	assert.equal(parsed.survivors_omitted, 0);
});

test("survivors are sorted by file and line before capping, so the kept set is stable", () => {
	const parsed = parseStrykerReport(reportWith(30), 3);
	assert.deepEqual(parsed.survivors.map((s) => s.line), [1, 2, 3]);
});

test("the cap flows through runMutate into the reported result", () => {
	const { dir, cleanup } = tmpRepo();
	try {
		writeReport(dir, reportWith(25));
		const r = runMutate({ cwd: dir, base: "HEAD", gitDiff: () => DIFF, runStryker: () => ({ ok: true, timedOut: false }) });
		assert.equal(r.survived, 25);
		assert.equal(r.survivors!.length, 20);
		assert.equal(r.survivors_omitted, 5);
	} finally {
		cleanup();
	}
});

test/mutate-cli.test.ts.source:
import { mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { test } from "node:test";
import assert from "node:assert/strict";
import { main, run, numFlag, type MutateIo } from "../src/mutate-cli.ts";
import { makeGitDiff, makeRunStryker, makeUntracked, type Exec, type ExecResult } from "../src/mutate-shell.ts";

const OK: ExecResult = { status: 0, stdout: "", stderr: "" };

function harness(opts: { withConfig?: boolean; exec?: Exec; files?: Record<string, string> } = {}) {
	const dir = mkdtempSync(join(tmpdir(), "craft-mutate-cli-"));
	if (opts.withConfig !== false) writeFileSync(join(dir, "stryker.config.json"), "{}");
	const out: string[] = [];
	const err: string[] = [];
	const io: MutateIo = {
		write: (s) => out.push(s),
		error: (s) => err.push(s),
		cwd: () => dir,
		exec: opts.exec ?? (() => OK),
		readFile: (p) => {
			const key = Object.keys(opts.files ?? {}).find((k) => p.endsWith(k));
			if (key === undefined) throw new Error(`no such file: ${p}`);
			return opts.files![key];
		},
	};
	return {
		io,
		dir,
		out: () => out.join(""),
		err: () => err.join(""),
		json: () => JSON.parse(out.join("")),
		cleanup: () => rmSync(dir, { recursive: true, force: true }),
	};
}

test("--help prints usage and succeeds", () => {
	const h = harness();
	try {
		assert.equal(main(["--help"], h.io), 0);
		assert.match(h.out(), /^craft-mutate —/);
	} finally {
		h.cleanup();
	}
});

test("a missing --base exits 2 rather than diffing against nothing", () => {
	const h = harness();
	try {
		assert.equal(main([], h.io), 2);
		assert.match(h.err(), /missing --base/);
	} finally {
		h.cleanup();
	}
});

test("a repo with no stryker config skips and still exits 0", () => {
	const h = harness({ withConfig: false });
	try {
		assert.equal(main(["--base", "HEAD"], h.io), 0, "no backend is not a failure");
		assert.deepEqual(h.json(), { status: "skipped", reason: "no-backend" });
	} finally {
		h.cleanup();
	}
});

test("an unparseable numeric flag is rejected, not silently defaulted", () => {
	for (const flag of ["--timeout", "--max-lines"]) {
		const h = harness();
		try {
			assert.equal(run(["--base", "HEAD", flag, "abc"], h.io), 2, flag);
			assert.match(h.err(), new RegExp(`invalid ${flag} abc`));
		} finally {
			h.cleanup();
		}
	}
});

test("a non-positive numeric flag is rejected", () => {
	const h = harness();
	try {
		assert.equal(run(["--base", "HEAD", "--timeout", "0"], h.io), 2);
	} finally {
		h.cleanup();
	}
});

test("an absent numeric flag falls back without complaint", () => {
	const h = harness();
	try {
		assert.equal(numFlag("--timeout", ["--base", "HEAD"], 60, h.io), 60);
		assert.equal(h.err(), "");
	} finally {
		h.cleanup();
	}
});

test("a failing git diff exits 1 rather than reporting no changes", () => {
	// The dangerous failure: an unresolvable base scoping nothing is
	// indistinguishable from a clean diff unless it is treated as fatal.
	const exec: Exec = (cmd, args) =>
		cmd === "git" && args[0] === "diff"
			? { status: 128, stdout: "", stderr: "fatal: bad revision 'nope'" }
			: OK;
	const h = harness({ exec });
	try {
		assert.equal(run(["--base", "nope"], h.io), 1);
		assert.match(h.err(), /bad revision/);
	} finally {
		h.cleanup();
	}
});

test("the shell adapters compose into a scoped stryker invocation", () => {
	const calls: Array<{ cmd: string; args: string[] }> = [];
	const exec: Exec = (cmd, args) => {
		calls.push({ cmd, args });
		if (cmd === "git" && args[0] === "diff") {
			return { status: 0, stdout: ["--- a/src/a.ts", "+++ b/src/a.ts", "@@ -1,0 +10,3 @@", "+x"].join("\n"), stderr: "" };
		}
		return OK;
	};
	const h = harness({ exec });
	try {
		// Stryker writes no report here, so the run reports an error — the point is
		// the arguments it was invoked with.
		run(["--base", "main"], h.io);
		const stryker = calls.find((c) => c.cmd === "npx");
		assert.ok(stryker, "stryker must be invoked");
		assert.deepEqual(stryker!.args, ["stryker", "run", "--mutate", "src/a.ts:10:1-13:1", "--reporters", "json"]);
	} finally {
		h.cleanup();
	}
});

// --- shell adapters, unit level ---

test("git diff failure calls fail rather than returning empty", () => {
	let failed = "";
	const gitDiff = makeGitDiff(() => ({ status: 1, stdout: "", stderr: "boom" }), (m) => {
		failed = m;
		throw new Error("failed");
	});
	assert.throws(() => gitDiff("/tmp", "HEAD"));
	assert.equal(failed, "boom");
});

test("git diff with an empty stderr still reports which ref failed", () => {
	let failed = "";
	const gitDiff = makeGitDiff(() => ({ status: 1, stdout: "", stderr: "   " }), (m) => {
		failed = m;
		throw new Error("failed");
	});
	assert.throws(() => gitDiff("/tmp", "deadbeef"));
	assert.match(failed, /deadbeef/);
});

test("untracked counts lines per file and drops unreadable ones", () => {
	const untracked = makeUntracked(
		() => ({ status: 0, stdout: "src/a.ts\nsrc/gone.ts\n\n  src/b.ts  \n", stderr: "" }),
		(p) => {
			if (p.endsWith("gone.ts")) throw new Error("ENOENT");
			return p.endsWith("a.ts") ? "one\ntwo\nthree" : "solo";
		},
		(a, b) => `${a}/${b}`,
	);
	assert.deepEqual(untracked("/repo"), [
		{ file: "src/a.ts", lines: 3 },
		{ file: "src/gone.ts", lines: 0 },
		{ file: "src/b.ts", lines: 1 },
	]);
});

test("untracked treats a non-repo as having nothing untracked", () => {
	const untracked = makeUntracked(() => ({ status: 128, stdout: "", stderr: "not a git repo" }), () => "", (a, b) => `${a}/${b}`);
	assert.deepEqual(untracked("/tmp"), []);
});

test("a timeout is detected from ETIMEDOUT or a kill signal, not from exit status", () => {
	// All three shapes mean "we ran out of time", and none of them is a nonzero
	// status — treating them as ordinary failures would report a broken run.
	for (const result of [
		{ status: null, stdout: "", stderr: "", error: { code: "ETIMEDOUT" } },
		{ status: null, stdout: "", stderr: "", signal: "SIGTERM" },
		{ status: null, stdout: "", stderr: "", signal: "SIGKILL" },
	] as ExecResult[]) {
		const outcome = makeRunStryker(() => result)("/repo", ["src/a.ts:1:1-2:1"], 60);
		assert.equal(outcome.timedOut, true, JSON.stringify(result));
		assert.equal(outcome.ok, false);
	}
});

test("a clean stryker run is neither failed nor timed out", () => {
	const outcome = makeRunStryker(() => OK)("/repo", ["src/a.ts:1:1-2:1"], 60);
	assert.equal(outcome.ok, true);
	assert.equal(outcome.timedOut, false);
});

test("stryker failure keeps only the tail of its stderr", () => {
	const stderr = ["line one", "line two", "line three", "line four", "line five"].join("\n");
	const outcome = makeRunStryker(() => ({ status: 1, stdout: "", stderr }))("/repo", [], 60);
	assert.equal(outcome.ok, false);
	assert.equal(outcome.detail, "line three\nline four\nline five");
});

test("the timeout is passed through to exec in milliseconds", () => {
	let seen: number | undefined;
	const outcome = makeRunStryker((_c, _a, opts) => {
		seen = opts.timeoutMs;
		return OK;
	})("/repo", [], 45);
	assert.equal(seen, 45_000, "seconds on the flag, milliseconds to the child");
	assert.equal(outcome.ok, true);
});

test/hooks-install.test.ts.source:
import { test } from "node:test";
import assert from "node:assert/strict";
import { HOOK_EVENTS, withHooks, type Settings } from "../src/hooks-install.ts";
import { main, type Io } from "../src/hooks-install-cli.ts";

const COMMAND = "/home/k/.local/bin/craft-hook";

test("every event the adapter handles is registered, with PreToolUse narrowed", () => {
	const { settings, added } = withHooks({}, COMMAND);
	assert.deepEqual(added.sort(), HOOK_EVENTS.map((h) => h.event).sort());
	assert.equal(settings.hooks!.PostToolUse[0].hooks![0].command, COMMAND);
	assert.equal(settings.hooks!.PostToolUse[0].matcher, undefined, "usage billing runs on every tool");
	// The one handler that rewrites tool input should not sit in front of every Read.
	assert.equal(settings.hooks!.PreToolUse[0].matcher, "Agent|Task");
});

test("re-running adds nothing — link-global is run often", () => {
	const once = withHooks({}, COMMAND).settings;
	const twice = withHooks(once, COMMAND);
	assert.deepEqual(twice.added, []);
	assert.deepEqual(twice.settings, once);
});

test("existing hooks and unrelated settings survive untouched", () => {
	const before: Settings = {
		model: "opus",
		permissions: { allow: ["Bash(git add *)"] },
		hooks: {
			PostToolUse: [{ hooks: [{ type: "command", command: "/usr/local/bin/my-linter" }] }],
			PreToolUse: [{ matcher: "Write", hooks: [{ type: "command", command: "/usr/local/bin/guard" }] }],
		},
	};
	const { settings } = withHooks(before, COMMAND);

	assert.equal(settings.model, "opus");
	assert.deepEqual(settings.permissions, { allow: ["Bash(git add *)"] });
	assert.equal(settings.hooks!.PostToolUse[0].hooks![0].command, "/usr/local/bin/my-linter");
	assert.equal(settings.hooks!.PostToolUse[1].hooks![0].command, COMMAND);
	// A different matcher on the same event is a different registration, not a clash.
	assert.equal(settings.hooks!.PreToolUse.length, 2);
	assert.equal(settings.hooks!.PreToolUse[0].matcher, "Write");
	assert.equal(settings.hooks!.PreToolUse[1].matcher, "Agent|Task");
	assert.equal((before.hooks!.PostToolUse as unknown[]).length, 1, "the input is not mutated");
});

test("the same command under a different matcher still registers", () => {
	const before: Settings = {
		hooks: { PreToolUse: [{ matcher: "Edit", hooks: [{ type: "command", command: COMMAND }] }] },
	};
	const { added } = withHooks(before, COMMAND);
	assert.equal(added.includes("PreToolUse"), true, "an Edit-scoped hook does not cover Agent|Task");
});

function harness(files: Record<string, string>) {
	const out: string[] = [];
	const err: string[] = [];
	const saved: Record<string, string> = { ...files };
	const io: Io = {
		write: (s) => out.push(s),
		error: (s) => err.push(s),
		read: (path) => files[path],
		save: (path, contents) => {
			saved[path] = contents;
		},
		backup: (from, to) => {
			saved[to] = files[from];
		},
	};
	return { io, out: () => out.join(""), err: () => err.join(""), saved };
}

test("the previous settings file is backed up before it is rewritten", () => {
	const h = harness({ "/s.json": JSON.stringify({ model: "opus" }) });
	assert.equal(main(["/s.json"], h.io, COMMAND), 0);
	assert.equal(JSON.parse(h.saved["/s.json.craft-backup"]).model, "opus");
	assert.equal(JSON.parse(h.saved["/s.json"]).hooks.Stop[0].hooks[0].command, COMMAND);
	assert.match(h.out(), /restart any open session/, "hooks are read at startup, not live");
});

test("a settings file that will not parse is left completely alone", () => {
	const h = harness({ "/s.json": "{ not json" });
	assert.equal(main(["/s.json"], h.io, COMMAND), 1);
	assert.equal(h.saved["/s.json"], "{ not json");
	assert.equal(h.saved["/s.json.craft-backup"], undefined, "nothing was touched, so nothing was backed up");
	assert.match(h.err(), /refusing to touch/);
});

test("a missing settings file is created without a backup of nothing", () => {
	const h = harness({});
	assert.equal(main(["/new.json"], h.io, COMMAND), 0);
	assert.equal(h.saved["/new.json.craft-backup"], undefined);
	assert.ok(JSON.parse(h.saved["/new.json"]).hooks.SessionStart);
});

test("a second run reports the no-op instead of rewriting the file", () => {
	const first = harness({});
	main(["/s.json"], first.io, COMMAND);
	const second = harness({ "/s.json": first.saved["/s.json"] });
	assert.equal(main(["/s.json"], second.io, COMMAND), 0);
	assert.match(second.out(), /already registered/);
	assert.equal(second.saved["/s.json.craft-backup"], undefined);
});

test("no path argument exits 2", () => {
	const h = harness({});
	assert.equal(main([], h.io, COMMAND), 2);
	assert.match(h.err(), /usage:/);
});

test/diff-ranges.test.ts.source:
import { test } from "node:test";
import assert from "node:assert/strict";
import {
	countLines,
	filterSourceRanges,
	mergeRanges,
	parseDiffRanges,
	toStrykerMutateArgs,
} from "../src/diff-ranges.ts";

test("parses a normal hunk into an inclusive range", () => {
	const diff = ["--- a/src/a.ts", "+++ b/src/a.ts", "@@ -10,3 +10,4 @@", "+one", "+two"].join("\n");
	assert.deepEqual(parseDiffRanges(diff), [{ file: "src/a.ts", start: 10, end: 13 }]);
});

test("an omitted count means exactly one line", () => {
	const diff = ["--- a/src/a.ts", "+++ b/src/a.ts", "@@ -10 +10 @@", "+one"].join("\n");
	assert.deepEqual(parseDiffRanges(diff), [{ file: "src/a.ts", start: 10, end: 10 }]);
});

test("a new file yields a range covering the whole file", () => {
	const diff = ["--- /dev/null", "+++ b/src/new.ts", "@@ -0,0 +1,50 @@"].join("\n");
	assert.deepEqual(parseDiffRanges(diff), [{ file: "src/new.ts", start: 1, end: 50 }]);
});

test("a pure deletion yields no range — nothing remains to mutate", () => {
	const diff = ["--- a/src/a.ts", "+++ b/src/a.ts", "@@ -10,5 +9,0 @@", "-gone"].join("\n");
	assert.deepEqual(parseDiffRanges(diff), []);
});

test("a deleted file yields no range", () => {
	const diff = ["--- a/src/gone.ts", "+++ /dev/null", "@@ -1,20 +0,0 @@"].join("\n");
	assert.deepEqual(parseDiffRanges(diff), []);
});

test("multiple files and hunks are all captured", () => {
	const diff = [
		"--- a/src/a.ts",
		"+++ b/src/a.ts",
		"@@ -1,0 +2,1 @@",
		"+x",
		"@@ -20,0 +30,3 @@",
		"+y",
		"--- a/src/b.ts",
		"+++ b/src/b.ts",
		"@@ -5,2 +5,2 @@",
		"+z",
	].join("\n");
	assert.deepEqual(parseDiffRanges(diff), [
		{ file: "src/a.ts", start: 2, end: 2 },
		{ file: "src/a.ts", start: 30, end: 32 },
		{ file: "src/b.ts", start: 5, end: 6 },
	]);
});

test("hunks before any file header are ignored rather than misattributed", () => {
	const diff = ["@@ -1,2 +1,2 @@", "+orphan"].join("\n");
	assert.deepEqual(parseDiffRanges(diff), []);
});

test("filters out test files and anything outside the source globs", () => {
	const ranges = [
		{ file: "src/a.ts", start: 1, end: 2 },
		{ file: "test/a.test.ts", start: 1, end: 2 },
		{ file: "docs/readme.md", start: 1, end: 2 },
	];
	const kept = filterSourceRanges(ranges, { include: [/^src\/.*\.ts$/], exclude: [/\.test\.ts$/] });
	assert.deepEqual(kept, [{ file: "src/a.ts", start: 1, end: 2 }]);
});

test("merges overlapping and abutting ranges, leaves separated ones alone", () => {
	const merged = mergeRanges([
		{ file: "src/a.ts", start: 10, end: 12 },
		{ file: "src/a.ts", start: 13, end: 15 }, // abuts
		{ file: "src/a.ts", start: 14, end: 20 }, // overlaps
		{ file: "src/a.ts", start: 40, end: 41 }, // separate
	]);
	assert.deepEqual(merged, [
		{ file: "src/a.ts", start: 10, end: 20 },
		{ file: "src/a.ts", start: 40, end: 41 },
	]);
});

test("merging keeps files independent", () => {
	const merged = mergeRanges([
		{ file: "src/b.ts", start: 1, end: 2 },
		{ file: "src/a.ts", start: 1, end: 2 },
	]);
	assert.equal(merged.length, 2);
	assert.equal(merged[0].file, "src/a.ts");
});

test("stryker range syntax spans the line inclusively", () => {
	// Column 1 of the line after the range is what makes the last line inclusive.
	assert.deepEqual(toStrykerMutateArgs([{ file: "src/a.ts", start: 70, end: 89 }]), ["src/a.ts:70:1-90:1"]);
});

test("countLines is inclusive of both ends", () => {
	assert.equal(countLines([{ file: "a", start: 10, end: 10 }]), 1);
	assert.equal(countLines([{ file: "a", start: 1, end: 5 }, { file: "b", start: 1, end: 3 }]), 8);
});

// --- gaps found by mutation testing, not by review ---

test("a hunk header with multi-digit counts still parses", () => {
	// `(?:,\d+)?` losing its `+` narrows the old-count to one digit and the whole
	// header stops matching. Every earlier fixture used single-digit old counts,
	// so nothing caught it.
	const diff = ["--- a/src/a.ts", "+++ b/src/a.ts", "@@ -100,25 +200,30 @@", "+x"].join("\n");
	assert.deepEqual(parseDiffRanges(diff), [{ file: "src/a.ts", start: 200, end: 229 }]);
});

test("a deleted file clears the current file rather than inheriting it", () => {
	// Without matching `+++ /dev/null`, `file` stays pointed at the previous entry
	// and the deleted file's hunks are attributed to it.
	const diff = [
		"--- a/src/kept.ts",
		"+++ b/src/kept.ts",
		"@@ -1,0 +5,2 @@",
		"+x",
		"--- a/src/gone.ts",
		"+++ /dev/null",
		"@@ -1,20 +0,0 @@",
	].join("\n");
	assert.deepEqual(parseDiffRanges(diff), [{ file: "src/kept.ts", start: 5, end: 6 }]);
});

test("include is an any-match, not an all-match", () => {
	// With a single include pattern `some` and `every` behave identically, so a
	// second pattern is what proves the intent.
	const ranges = [{ file: "src/a.ts", start: 1, end: 2 }];
	const kept = filterSourceRanges(ranges, { include: [/^lib\//, /^src\//], exclude: [] });
	assert.deepEqual(kept, ranges, "matching any one include pattern is enough");
});

test("exclude is an any-match: one matching pattern is enough to drop a file", () => {
	const ranges = [{ file: "src/a.test.ts", start: 1, end: 2 }];
	const kept = filterSourceRanges(ranges, {
		include: [/^src\//],
		exclude: [/\.test\.ts$/, /^vendor\//],
	});
	assert.deepEqual(kept, [], "matching one exclude pattern drops it, not all of them");
});

test("ranges arriving out of order are sorted before merging", () => {
	// Earlier fixtures were already ordered, so removing the comparator changed
	// nothing and the mutant lived.
	const merged = mergeRanges([
		{ file: "src/a.ts", start: 40, end: 41 },
		{ file: "src/a.ts", start: 10, end: 12 },
		{ file: "src/a.ts", start: 13, end: 15 },
	]);
	assert.deepEqual(merged, [
		{ file: "src/a.ts", start: 10, end: 15 },
		{ file: "src/a.ts", start: 40, end: 41 },
	]);
});

test/cli.test.ts.source:
import { mkdtempSync, readFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { test } from "node:test";
import assert from "node:assert/strict";
import { main, mtok, run, type Io } from "../src/cli.ts";
import type { PriceTable } from "../src/pricing.ts";

/**
 * The CLI reaches for `process` for output, exit codes, cwd and the clock. All of
 * it is injected here so a command that rejects bad input can be asserted on
 * instead of taking the test runner down with it.
 *
 * An empty price table by default: notional pricing must not depend on whatever
 * happens to be in this machine's pi model registry.
 */
function harness(prices: PriceTable = new Map()) {
	const dir = mkdtempSync(join(tmpdir(), "craft-cli-"));
	const out: string[] = [];
	const err: string[] = [];
	const io: Io = {
		write: (s) => out.push(s),
		error: (s) => err.push(s),
		cwd: () => "/tmp/project",
		now: () => Date.parse("2026-04-08T12:00:00.000Z"),
		storePath: () => join(dir, "events.jsonl"),
		prices,
	};
	return {
		io,
		out: () => out.join(""),
		err: () => err.join(""),
		events: () => {
			try {
				return readFileSync(join(dir, "events.jsonl"), "utf8").trim().split("\n").filter(Boolean).map((l) => JSON.parse(l));
			} catch {
				return [];
			}
		},
		cleanup: () => rmSync(dir, { recursive: true, force: true }),
	};
}

test("no command prints usage and succeeds", () => {
	const h = harness();
	try {
		assert.equal(main([], h.io), 0);
		assert.match(h.out(), /^craft-metrics —/);
	} finally {
		h.cleanup();
	}
});

test("--help and -h both print usage", () => {
	for (const flag of ["--help", "-h"]) {
		const h = harness();
		try {
			assert.equal(main([flag], h.io), 0);
			assert.match(h.out(), /Usage:/);
		} finally {
			h.cleanup();
		}
	}
});

test("an unknown command exits 2 and shows usage", () => {
	const h = harness();
	try {
		assert.equal(main(["frobnicate"], h.io), 2);
		assert.match(h.err(), /unknown command frobnicate/);
		assert.match(h.out(), /Usage:/);
	} finally {
		h.cleanup();
	}
});

test("start writes a run and echoes its id", () => {
	const h = harness();
	try {
		assert.equal(main(["start", "--kind", "feature", "--mode", "full"], h.io), 0);
		const id = h.out().trim();
		assert.match(id, /^[0-9a-f-]{36}$/);
		const opened = h.events().find((e) => e.t === "run_open");
		assert.equal(opened.kind, "feature");
		assert.equal(opened.mode, "full");
		// cwd and repo both fall back to the injected working directory.
		assert.equal(opened.cwd, "/tmp/project");
		assert.equal(opened.repo, "project");
	} finally {
		h.cleanup();
	}
});

test("start records an explicit craft version", () => {
	const h = harness();
	try {
		main(["start", "--kind", "docs", "--mode", "lite", "--craft-version", "4"], h.io);
		assert.equal(h.events().find((e) => e.t === "run_open").craft_version, "4");
	} finally {
		h.cleanup();
	}
});

test("an invalid kind, mode, or phase exits 2 with a specific message", () => {
	const cases: Array<[string[], RegExp]> = [
		[["start", "--kind", "wat", "--mode", "full"], /invalid --kind wat/],
		[["start", "--kind", "feature", "--mode", "wat"], /invalid --mode wat/],
		[["enter", "--run", "x", "--phase", "wat"], /invalid --phase wat/],
		// Derived buckets are not gates a caller may enter.
		[["enter", "--run", "x", "--phase", "unattributed"], /invalid --phase unattributed/],
		// Host decides which population a run is compared within, so a near-miss
		// spelling must fail rather than quietly open a third harness.
		[["start", "--kind", "feature", "--mode", "full", "--host", "claude"], /invalid --host claude/],
	];
	for (const [argv, expected] of cases) {
		const h = harness();
		try {
			assert.equal(run(argv, h.io), 2, argv.join(" "));
			assert.match(h.err(), expected);
		} finally {
			h.cleanup();
		}
	}
});

test("a missing required flag exits 2 and names the flag", () => {
	const h = harness();
	try {
		assert.equal(run(["enter", "--phase", "C"], h.io), 2);
		assert.match(h.err(), /missing --run/);
	} finally {
		h.cleanup();
	}
});

test("enter and exit round-trip a phase with its fields", () => {
	const h = harness();
	try {
		main(["start", "--kind", "feature", "--mode", "full"], h.io);
		const id = h.out().trim();
		assert.equal(main(["enter", "--run", id, "--phase", "C", "--agent", "craft-planner"], h.io), 0);
		assert.equal(
			main(["exit", "--run", id, "--phase", "C", "--security-triggers", "untrusted-input,secrets-sensitive-data", "--blocking-questions", "2"], h.io),
			0,
		);
		const exit = h.events().find((e) => e.t === "phase_exit");
		assert.deepEqual(exit.fields.security_triggers, ["untrusted-input", "secrets-sensitive-data"]);
		assert.equal(exit.fields.blocking_questions, 2);
	} finally {
		h.cleanup();
	}
});

test("an empty --security-triggers yields an empty list, not a list of one empty string", () => {
	const h = harness();
	try {
		main(["start", "--kind", "feature", "--mode", "full"], h.io);
		const id = h.out().trim();
		main(["enter", "--run", id, "--phase", "C"], h.io);
		main(["exit", "--run", id, "--phase", "C", "--security-triggers", ""], h.io);
		assert.deepEqual(h.events().find((e) => e.t === "phase_exit").fields.security_triggers, []);
	} finally {
		h.cleanup();
	}
});

test("lite mode refuses a counsel phase, surfacing the store's guard as exit 2", () => {
	const h = harness();
	try {
		main(["start", "--kind", "feature", "--mode", "lite"], h.io);
		const id = h.out().trim();
		assert.equal(run(["enter", "--run", id, "--phase", "counsel"], h.io), 2);
		assert.match(h.err(), /mode=lite/);
	} finally {
		h.cleanup();
	}
});

test("verify requires a numeric exit code", () => {
	const h = harness();
	try {
		main(["start", "--kind", "feature", "--mode", "full"], h.io);
		const id = h.out().trim();
		assert.equal(run(["verify", "--run", id, "--command", "npm test"], h.io), 2);
		assert.match(h.err(), /missing or invalid --exit-code/);
	} finally {
		h.cleanup();
	}
});

test("verify records the command and its exit code", () => {
	const h = harness();
	try {
		main(["start", "--kind", "feature", "--mode", "full"], h.io);
		const id = h.out().trim();
		assert.equal(main(["verify", "--run", id, "--command", "npm test", "--exit-code", "1"], h.io), 0);
		const v = h.events().find((e) => e.t === "verify");
		assert.equal(v.command, "npm test");
		assert.equal(v.exit_code, 1);
	} finally {
		h.cleanup();
	}
});

test("A cannot exit with a pass verdict while verification is red", () => {
	const h = harness();
	try {
		main(["start", "--kind", "feature", "--mode", "full"], h.io);
		const id = h.out().trim();
		main(["enter", "--run", id, "--phase", "A"], h.io);
		main(["verify", "--run", id, "--command", "npm test", "--exit-code", "1"], h.io);
		assert.equal(run(["exit", "--run", id, "--phase", "A", "--verdict", "pass"], h.io), 2);
		assert.match(h.err(), /verification is red/);
	} finally {
		h.cleanup();
	}
});

test("current exits 1 when no run is open for the directory", () => {
	const h = harness();
	try {
		assert.equal(main(["current", "--cwd", "/tmp/nothing-here"], h.io), 1);
		assert.equal(h.out(), "");
	} finally {
		h.cleanup();
	}
});

test("current prints the open run for a directory", () => {
	const h = harness();
	try {
		main(["start", "--kind", "feature", "--mode", "full", "--cwd", "/tmp/proj"], h.io);
		const id = h.out().trim();
		assert.equal(main(["current", "--cwd", "/tmp/proj"], h.io), 0);
		assert.ok(h.out().includes(id));
	} finally {
		h.cleanup();
	}
});

test("doctor exits 0 on clean data and 1 when it finds a problem", () => {
	const clean = harness();
	try {
		assert.equal(main(["doctor"], clean.io), 0);
		assert.match(clean.out(), /no data-quality problems found/);
	} finally {
		clean.cleanup();
	}

	const dirty = harness();
	try {
		// A run that never entered a phase is the "ungated" complaint.
		main(["start", "--kind", "feature", "--mode", "full"], dirty.io);
		const id = dirty.out().trim();
		main(["usage", "--run", id, "--cost", "1", "--turns", "1"], dirty.io);
		assert.equal(main(["doctor"], dirty.io), 1, "a complaint must produce a nonzero exit");
		assert.match(dirty.out(), /ungated/);
	} finally {
		dirty.cleanup();
	}
});

test("show reports nothing gracefully when there are no runs", () => {
	const h = harness();
	try {
		assert.equal(main(["show"], h.io), 0);
		assert.match(h.out(), /no craft runs recorded/);
	} finally {
		h.cleanup();
	}
});

test("show --run accepts an id prefix", () => {
	const h = harness();
	try {
		main(["start", "--kind", "feature", "--mode", "full"], h.io);
		const id = h.out().trim();
		assert.equal(main(["show", "--run", id.slice(0, 8)], h.io), 0);
		assert.ok(h.out().includes(id.slice(0, 8)));
	} finally {
		h.cleanup();
	}
});

test("models reports nothing gracefully when no model usage exists", () => {
	const h = harness();
	try {
		assert.equal(main(["models"], h.io), 0);
		assert.match(h.out(), /no model usage recorded/);
	} finally {
		h.cleanup();
	}
});

test("models marks a subscription model n/a and prices it notionally", () => {
	const prices: PriceTable = new Map([["openai-codex/gpt-5.6-terra", { input: 2, output: 12, cacheRead: 0.2, cacheWrite: 0 }]]);
	const h = harness(prices);
	try {
		main(["start", "--kind", "feature", "--mode", "full"], h.io);
		const id = h.out().trim();
		main(["enter", "--run", id, "--phase", "R"], h.io);
		main(["usage", "--run", id, "--model", "openai-codex/gpt-5.6-terra", "--cost", "0", "--input", "1000000", "--turns", "1"], h.io);
		main(["models"], h.io);
		const text = h.out();
		assert.match(text, /n\/a/, "a $0 subscription model reads n/a, not $0.00");
		assert.match(text, /\$\s*2\.00/, "its tokens still price at list rate");
		assert.match(text, /subscription-billed/);
	} finally {
		h.cleanup();
	}
});

test("totals splits by workflow version and labels inferred ones", () => {
	const h = harness();
	try {
		main(["start", "--kind", "feature", "--mode", "full", "--cwd", "/tmp/v3run"], h.io);
		const id = h.out().trim();
		// A craft-plan-* agent dates this run to v3 without any declaration.
		main(["enter", "--run", id, "--phase", "counsel", "--agent", "craft-plan-scope"], h.io);
		main(["totals"], h.io);
		const text = h.out();
		assert.match(text, /CRAFTS v3/);
		assert.match(text, /1 inferred/);
		assert.match(text, /Compare phases by notional, not cost/);
	} finally {
		h.cleanup();
	}
});

test("totals headings name the harness, and host corrects a mislabelled run", () => {
	const h = harness();
	try {
		main(["start", "--kind", "feature", "--mode", "full", "--craft-version", "4"], h.io);
		const id = h.out().trim();
		main(["enter", "--run", id, "--phase", "R", "--agent", "craft-builder"], h.io);
		main(["totals"], h.io);
		assert.match(h.out(), /CRAFTS v4 · unknown/, "a run with no declared host says so");

		assert.equal(main(["host", "--run", id, "--host", "claude-code"], h.io), 0);
		assert.equal(h.events().find((e) => e.t === "host").host, "claude-code");
		main(["totals"], h.io);
		assert.match(h.out(), /CRAFTS v4 · claude-code/);
		assert.match(h.out(), /Compare across hosts by notional or tokens only/);
	} finally {
		h.cleanup();
	}
});

test("doctor names a run that belongs to no harness", () => {
	const h = harness();
	try {
		main(["start", "--kind", "feature", "--mode", "full"], h.io);
		const id = h.out().trim();
		main(["enter", "--run", id, "--phase", "R"], h.io);
		assert.equal(main(["doctor"], h.io), 1);
		assert.match(h.out(), /unknown-host/);
		assert.match(h.out(), /cannot be compared against pi or claude-code/);
	} finally {
		h.cleanup();
	}
});

test("totals --all blends versions into a single table", () => {
	const h = harness();
	try {
		main(["start", "--kind", "feature", "--mode", "full"], h.io);
		const id = h.out().trim();
		main(["enter", "--run", id, "--phase", "counsel", "--agent", "craft-plan-scope"], h.io);
		main(["totals", "--all"], h.io);
		assert.ok(!h.out().includes("CRAFTS v"), "the blended table carries no version headings");
	} finally {
		h.cleanup();
	}
});

test("run turns an unexpected store error into exit 2 rather than a stack trace", () => {
	const h = harness();
	try {
		// No such run: the store throws, and `run` is what keeps it off the terminal.
		assert.equal(run(["enter", "--run", "does-not-exist", "--phase", "C"], h.io), 2);
		assert.match(h.err(), /unknown run does-not-exist/);
	} finally {
		h.cleanup();
	}
});

// --- gaps found by mutation testing, not by review ---

test("mtok abbreviates at each magnitude and pads to a fixed width", () => {
	// Boundaries in both directions: the thresholds are `>=`, so the value at the
	// threshold must abbreviate and the one below it must not.
	assert.equal(mtok(999).trim(), "999");
	assert.equal(mtok(1_000).trim(), "1k");
	assert.equal(mtok(999_999).trim(), "1000k", "just under a million still reads in k");
	assert.equal(mtok(1_000_000).trim(), "1.0M");
	assert.equal(mtok(2_500_000).trim(), "2.5M");
	assert.equal(mtok(0).trim(), "0");
	for (const n of [0, 999, 1_000, 1_000_000]) {
		assert.equal(mtok(n).length, 6, `every column is the same width: ${n}`);
	}
});

test("every valid mode and kind is accepted", () => {
	for (const mode of ["full", "hitl", "lite", "dag"]) {
		const h = harness();
		try {
			assert.equal(main(["start", "--kind", "feature", "--mode", mode], h.io), 0, mode);
			assert.equal(h.events().find((e) => e.t === "run_open").mode, mode);
		} finally {
			h.cleanup();
		}
	}
	for (const kind of ["feature", "bugfix", "refactor", "scaffold", "docs", "chore"]) {
		const h = harness();
		try {
			assert.equal(main(["start", "--kind", kind, "--mode", "full"], h.io), 0, kind);
			assert.equal(h.events().find((e) => e.t === "run_open").kind, kind);
		} finally {
			h.cleanup();
		}
	}
});

test("every gateable phase is accepted by enter", () => {
	for (const phase of ["C", "counsel", "R", "A", "F", "T", "S"]) {
		const h = harness();
		try {
			main(["start", "--kind", "feature", "--mode", "full"], h.io);
			const id = h.out().trim();
			assert.equal(main(["enter", "--run", id, "--phase", phase], h.io), 0, phase);
		} finally {
			h.cleanup();
		}
	}
});

test("pause and resume bracket a HITL wait", () => {
	const h = harness();
	try {
		main(["start", "--kind", "feature", "--mode", "hitl"], h.io);
		const id = h.out().trim();
		assert.equal(main(["pause", "--run", id], h.io), 0);
		assert.equal(main(["resume", "--run", id], h.io), 0);
		const kinds = h.events().map((e) => e.t);
		assert.ok(kinds.includes("hitl_pause") && kinds.includes("hitl_resume"));
	} finally {
		h.cleanup();
	}
});

test("mode and kind can be corrected after start", () => {
	const h = harness();
	try {
		main(["start", "--kind", "feature", "--mode", "full"], h.io);
		const id = h.out().trim();
		assert.equal(main(["mode", "--run", id, "--mode", "hitl"], h.io), 0);
		assert.equal(main(["kind", "--run", id, "--kind", "bugfix"], h.io), 0);
		const evs = h.events();
		assert.equal(evs.find((e) => e.t === "mode").mode, "hitl");
		assert.equal(evs.find((e) => e.t === "kind").kind, "bugfix");
	} finally {
		h.cleanup();
	}
});

test("end defaults to completed and accepts an explicit outcome", () => {
	const h = harness();
	try {
		main(["start", "--kind", "feature", "--mode", "full"], h.io);
		const id = h.out().trim();
		assert.equal(main(["end", "--run", id], h.io), 0);
		assert.equal(h.events().find((e) => e.t === "run_end").outcome, "completed");
	} finally {
		h.cleanup();
	}

	const h2 = harness();
	try {
		main(["start", "--kind", "feature", "--mode", "full"], h2.io);
		const id = h2.out().trim();
		main(["end", "--run", id, "--outcome", "blocked"], h2.io);
		assert.equal(h2.events().find((e) => e.t === "run_end").outcome, "blocked");
	} finally {
		h2.cleanup();
	}
});

test("usage records tokens, flags, and an explicit phase stamp", () => {
	const h = harness();
	try {
		main(["start", "--kind", "feature", "--mode", "full"], h.io);
		const id = h.out().trim();
		assert.equal(
			main(
				["usage", "--run", id, "--phase", "A", "--model", "xai/grok-4.6", "--provider", "xai",
					"--input", "100", "--output", "50", "--cache-read", "7", "--cache-write", "3",
					"--cost", "0.25", "--turns", "2", "--tool", "read", "--agent", "craft-evaluator",
					"--subagent", "--quota-error", "--timeout", "--failover", "--blinding-scrubs", "3"],
				h.io,
			),
			0,
		);
		const u = h.events().find((e) => e.t === "usage");
		assert.equal(u.phase, "A");
		assert.deepEqual(u.tokens, { input: 100, output: 50, cacheRead: 7, cacheWrite: 3 });
		assert.equal(u.cost_usd, 0.25);
		assert.equal(u.blinding_scrubs, 3);
		// Presence flags must be booleans, not the string that followed them.
		assert.equal(u.subagent, true);
		assert.equal(u.quota_error, true);
		assert.equal(u.failover, true);
	} finally {
		h.cleanup();
	}
});

test("usage without token flags records zeros rather than NaN", () => {
	const h = harness();
	try {
		main(["start", "--kind", "feature", "--mode", "full"], h.io);
		const id = h.out().trim();
		main(["usage", "--run", id, "--turns", "1"], h.io);
		const u = h.events().find((e) => e.t === "usage");
		assert.deepEqual(u.tokens, { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 });
	} finally {
		h.cleanup();
	}
});

test("show --last keeps only the most recent runs", () => {
	const h = harness();
	try {
		const ids: string[] = [];
		for (const cwd of ["/tmp/a", "/tmp/b", "/tmp/c"]) {
			main(["start", "--kind", "feature", "--mode", "full", "--cwd", cwd], h.io);
			ids.push(h.out().trim().split("\n").at(-1)!);
		}
		const before = h.out().length;
		main(["show", "--last", "1"], h.io);
		const shown = h.out().slice(before);
		assert.ok(shown.includes(ids[2].slice(0, 8)), "the newest run is shown");
		assert.ok(!shown.includes(ids[0].slice(0, 8)), "older runs are dropped");
	} finally {
		h.cleanup();
	}
});

test("pin-versions writes nothing without --apply", () => {
	const h = harness();
	try {
		main(["start", "--kind", "feature", "--mode", "full"], h.io);
		const id = h.out().trim();
		main(["enter", "--run", id, "--phase", "counsel", "--agent", "craft-plan-scope"], h.io);
		assert.equal(main(["pin-versions"], h.io), 0);
		assert.match(h.out(), /would be pinned/);
		assert.equal(h.events().filter((e) => e.t === "craft_version").length, 0, "a dry run must not write");
	} finally {
		h.cleanup();
	}
});

test("pin-versions --apply persists the inference with its provenance", () => {
	const h = harness();
	try {
		main(["start", "--kind", "feature", "--mode", "full"], h.io);
		const id = h.out().trim();
		main(["enter", "--run", id, "--phase", "counsel", "--agent", "craft-plan-scope"], h.io);
		assert.equal(main(["pin-versions", "--apply"], h.io), 0);
		const ev = h.events().filter((e) => e.t === "craft_version");
		assert.equal(ev.length, 1);
		assert.equal(ev[0].craft_version, "3");
		assert.equal(ev[0].source, "inferred");
		assert.match(h.out(), /still marked inferred, not declared/);
	} finally {
		h.cleanup();
	}
});

test("pin-versions leaves declared runs alone and says so when there is nothing to do", () => {
	const h = harness();
	try {
		main(["start", "--kind", "feature", "--mode", "full", "--craft-version", "4"], h.io);
		assert.equal(main(["pin-versions", "--apply"], h.io), 0);
		assert.match(h.out(), /nothing to pin/);
		assert.equal(h.events().filter((e) => e.t === "craft_version").length, 0);
	} finally {
		h.cleanup();
	}
});

